            {
                AlwaysLogSelectors = new List<Func<AuditLogInfo, Task<bool>>>
                {
                    async (info) => await Task.FromResult(true)
                }
            });

            serviceProviderMock.Setup(x => x.GetRequiredService<IOptions<AbpAuditingOptions>>()).Returns(auditingOptionsMock.Object);
            serviceProviderMock.Setup(x => x.GetRequiredService<IAuditingManager>()).Returns(auditingManagerMock.Object);
            serviceProviderMock.Setup(x => x.GetRequiredService<ICurrentUser>()).Returns(currentUserMock.Object);

            var filter = new AbpAuditHubFilter();

            // Act
            var result = await filter.ShouldWriteAuditLogAsync(auditLogInfo, serviceProviderMock.Object, false);

            // Assert
            Assert.True(result);
        }

